svg.script:
(function(){
var $=function(i){return document.getElementById(i)};
var P=[1,3*86400,1000*31557600],CX=[170,450,730],CY=190,R=100,MAXE=12,LIM=15;
var X0=150,X1=750,e=0,ph=[0,0,0],last=null,run=false,drag=false;
var d=[$('d0'),$('d1'),$('d2')],b=[$('b0'),$('b1'),$('b2')];
function fmt(s){
 var u=[[1,'s'],[60,'min'],[3600,'hr'],[86400,'day'],[31557600,'yr'],[31557600e3,'kyr']],i=0;
 while(i<u.length-1&&s>=u[i+1][0])i++;
 var v=s/u[i][0];return (v<10?v.toFixed(1):Math.round(v))+' '+u[i][1]+' / s';
}
function draw(){
 var s=Math.pow(10,e),any=false;
 $('knob').setAttribute('cx',X0+(X1-X0)*e/MAXE);
 $('read').textContent=fmt(s);
 for(var i=0;i<3;i++){
  var blurred=s/P[i]>LIM;
  b[i].style.display=blurred?'':'none';
  d[i].style.display=blurred?'none':'';
  if(!blurred){any=true;var a=ph[i]*2*Math.PI-Math.PI/2;
   d[i].setAttribute('cx',CX[i]+R*Math.cos(a));d[i].setAttribute('cy',CY+R*Math.sin(a));}
 }
 $('blur').setAttribute('visibility','visible');
 return any;
}
function tick(t){
 if(last!==null){var dt=(t-last)/1000,s=Math.pow(10,e);
  for(var i=0;i<3;i++)if(s/P[i]<=LIM)ph[i]=(ph[i]+dt*s/P[i])%1;}
 last=t;
 if(draw())requestAnimationFrame(tick);else{run=false;last=null;}
}
function go(){if(!run){run=true;last=null;requestAnimationFrame(tick);}}
function set(ev){
 var r=$('knob').ownerSVGElement.getBoundingClientRect(),x=(ev.clientX-r.left)*900/r.width;
 e=Math.max(0,Math.min(MAXE,(x-X0)/(X1-X0)*MAXE));go();
}
var k=$('knob'),svg=k.ownerSVGElement;
k.addEventListener('pointerdown',function(ev){drag=true;k.setPointerCapture(ev.pointerId);});
k.addEventListener('pointermove',function(ev){if(drag)set(ev);});
k.addEventListener('pointerup',function(){drag=false;});
svg.addEventListener('pointerdown',function(ev){if(ev.target!==k){set(ev);}});
k.addEventListener('keydown',function(ev){
 if(ev.key==='ArrowRight'||ev.key==='ArrowUp')e=Math.min(MAXE,e+0.25);
 else if(ev.key==='ArrowLeft'||ev.key==='ArrowDown')e=Math.max(0,e-0.25);else return;go();
});
draw();go();
})();
